import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_score as S  # noqa: E402
import p1v4_situation as SIT  # noqa: E402

R = "data/p1v4/runs"
EVENT = ("phone", "doorbell", "knock")
CONDS = ("natural", "none", "c0.3", "c0.5", "c0.7", "c0.9", "c0.99")
MATCHED = CONDS[1:]
# package v0.6 15.1: false movement labels for the stop decision (S-move groups only; R-hear groups read them as "none")
MOVE = ("footsteps", "door")
MOVE_CONDS = ("mv0.5", "mv0.9", "mv0.99")
S_CONDS = ("none",) + MOVE_CONDS                 # the conditions of every S-move criterion from v0.6
ALL_CONDS = CONDS + MOVE_CONDS
MERGE_GAP_S = 0.3                                # = p1v4_feats.MERGE_GAP_S, the detector's merge rule
FRAME_CAP = 0.1
FPS = 100
SETTINGS = {"b3": "A6_nothink", "b2fast": "K48_think_prec", "b2strong": "K48_nothink_prec"}   # frozen dev choices


def out_dir(split):
    return f"{R}/grounding/{split}"


def is_move(cond):
    return cond.startswith("mv")


def cval(cond):
    if cond in ("natural", "none"):
        return None
    return float(cond[2:]) if is_move(cond) else float(cond[1:])


def move_spans(r1, t):
    """Version 1's footsteps and door clips that start before the point, merged per class when the gap is below the
    detector's merge gap, clipped at the point: [(cls, start, end)]."""
    out = []
    for cls in MOVE:
        segs = sorted((s["start"], s["end"]) for s in r1["sources"]
                      if s["kind"] == "clip" and s.get("cls") == cls and s["start"] < t)
        merged = []
        for a, b in segs:
            if merged and a - merged[-1][1] < MERGE_GAP_S:
                merged[-1][1] = max(merged[-1][1], b)
            else:
                merged.append([a, b])
        out += [(cls, round(a, 3), round(min(b, t), 3)) for a, b in merged if min(b, t) > a]
    return out


def sha(x):
    return hashlib.sha1(x.encode("utf-8") if isinstance(x, str) else np.ascontiguousarray(x).tobytes()).hexdigest()


def load(split):
    final = split != "dev"
    rows = D.load_rows(split, final) if final else D.load_rows(split)
    return rows, {(r["unit"], r["version"]): r for r in rows}


def build_groups(rows):
    by = {}
    for r in rows:
        by.setdefault(r["unit"], {})[r["version"]] = r
    ex = S.excluded_units()
    groups, left = [], collections.Counter()
    for u, vs in sorted(by.items()):
        r1 = vs.get("1")
        if r1 is None or r1["part"] not in ("r_hear", "s_move"):
            continue
        part = r1["part"]
        if part == "s_move" and r1["spec"].get("visitor_speaks"):
            continue
        want = ("1", "2", "3") if part == "r_hear" else ("1", "2", "3", "4")
        if u in ex:
            left[f"{part}: excluded unit"] += 1
            continue
        if set(vs) != set(want):
            left[f"{part}: versions missing"] += 1
            continue
        ks = [p["k"] for p in r1["points"]]
        same = all([p["k"] for p in vs[v]["points"]] == ks
                   and all(abs(a["t"] - b["t"]) < 1e-6 for a, b in zip(vs[v]["points"], r1["points"])) for v in want)
        if not same or len(ks) != 1:
            left[f"{part}: points differ"] += 1
            continue
        t = r1["points"][0]["t"]
        ev = [s for s in r1["sources"] if s["kind"] == "clip" and s.get("cls") in EVENT and s["start"] < t]
        if not ev:
            left[f"{part}: no phone, doorbell or knock clip (e.g. vibration)"] += 1
            continue
        cls = ev[-1]["cls"]
        s0 = min(s["start"] for s in ev if s["cls"] == cls)
        s1 = min(max(s["end"] for s in ev if s["cls"] == cls), t)
        groups.append({"unit": u, "part": part, "versions": list(want), "k": ks[0], "t": t,
                       "event": [cls, round(s0, 3), round(s1, 3)]})
    return groups, dict(left)


def matched_context(base):
    class Matched(base):
        """Matched inputs of plan 4.2 for the points of the groups; every other point unchanged."""

        def __init__(self, which, groups, cond, rows_by, **kw):
            super().__init__(which, **kw)
            self.cond, self.rows_by = cond, rows_by
            self.gmap = {(g["unit"], v, g["k"]): g for g in groups for v in g["versions"]}

        def point(self, r, k):
            g = self.gmap.get((r["unit"], r["version"], k))
            if g is None or self.cond == "natural":
                return super().point(r, k)
            tr, sc, tags, snd = base.point(self, self.rows_by[(r["unit"], "2")], k)
            snd = [s for s in snd if s[0] not in EVENT]
            c = cval(self.cond)
            if is_move(self.cond):                     # v0.6 15.1: S-move groups get version 1's movement spans at c
                if g["part"] == "s_move":
                    snd = [s for s in snd if s[0] not in MOVE]
                    add = [(cls, a, b, c) for cls, a, b in move_spans(self.rows_by[(r["unit"], "1")], g["t"])]
                    snd = sorted(snd + add, key=lambda s: (s[1], s[0]))
            elif c is not None:
                cls, s0, s1 = g["event"]
                snd = sorted(snd + [(cls, s0, s1, c)], key=lambda s: (s[1], s[0]))
            return tr, sc, tags, snd

        def situation(self, r, k, variant="full"):
            g = self.gmap.get((r["unit"], r["version"], k))
            if g is None or self.cond == "natural":
                return super().situation(r, k, variant)
            rb = self.rows_by[(r["unit"], "2")]
            tr, _, tags, snd = self.point(rb, k)
            return SIT.build(rb, k, tr, tags, snd, variant)

    return Matched


def patch_context(groups, cond, rows_by):
    """C.Context -> the matched context of `cond` for code that builds its own C.Context(which)."""
    base = C.Context
    M = matched_context(base)

    class Patched(M):
        def __init__(self, which, **kw):
            super().__init__(which, groups, cond, rows_by, **kw)

    C.Context = Patched
    return base


def groups_cmd(split):
    rows, _ = load(split)
    groups, left = build_groups(rows)
    os.makedirs(out_dir(split), exist_ok=True)
    json.dump({"groups": groups, "left_out": left}, open(f"{out_dir(split)}/groups.json", "w"), indent=1)
    n = collections.Counter(g["part"] for g in groups)
    cls = collections.Counter((g["part"], g["event"][0]) for g in groups)
    print(f"{split}: {dict(n)} groups; by event class {dict(cls)}; left out {left}")
    return groups


def load_groups(split):
    p = f"{out_dir(split)}/groups.json"
    if not os.path.exists(p):
        return groups_cmd(split)
    return json.load(open(p))["groups"]


# ------------------------------------------------------------------------------------------------ L1 family

def l1_cmd(split):
    from p1v4_readout_2d import per_second           # imported here: p1v4_readout_2d imports this module
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    D.gpu_guard()
    rows, rows_by = load(split)
    groups = load_groups(split)
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    wins = [w for w in D.windows_of(rows, split) if (w["unit"], w["version"], w["k"]) in keys]
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    M = matched_context(C.Context)
    part_of = {g["unit"]: g["part"] for g in groups}
    for cond in ALL_CONDS:
        path = f"{out_dir(split)}/l1_{cond}.npz"
        if os.path.exists(path):
            print(f"{cond}: exists, skipped", flush=True)
            continue
        ctx = M(split, groups, cond, rows_by, final=split != "dev")
        items = []
        for w in wins:
            if is_move(cond) and part_of[w["unit"]] != "s_move":     # v0.6 15.1: S-move groups only
                continue
            r = rows_by[(w["unit"], w["version"])]
            text, asks = ctx.situation(r, w["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            snd = [s for s in ctx.point(r, w["k"])[3] if RO.in_window(s, w["t"])]
            items.append({"id": w["id"], "unit": w["unit"], "part": w["part"], "path": w["path"], "text": text,
                          "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                          "gold": [-1 if w["gold"].get(q) is None else
                                   int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                          "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0)})
        H, E, SM, SX, QW, QT, QG, PO = [], [], [], [], [], [], [], []
        t0 = time.time()
        for i, it in enumerate(items):                         # batch 1 (plan 4.6)
            wave = torch.from_numpy(sf.read(it["path"], dtype="float32")[0])[None].cuda()
            h, e, qs, po = RO.forward_states(model, wave, [it["text"]], [it["marker"]],
                                             [[RO.TASK[q] for q in it["qs"]]])
            sm, sx, _ = per_second(model.vt, wave)          # step 2d's per-second ears (v0.5), same batch 1
            H.append(h.astype(np.float16))
            E.append(e.astype(np.float16))
            SM.append(sm.astype(np.float16))
            SX.append(sx.astype(np.float16))
            QW.append(qs + i)
            QT += it["qs"]
            QG += it["gold"]
            PO.append(po)
            if i % 300 == 0:
                print(f"{split}/{cond}: {i + 1}/{len(items)} windows {time.time() - t0:.0f} s", flush=True)
        np.savez(path, states=np.concatenate(H), ears=np.concatenate(E), sec_mean=np.concatenate(SM),
                 sec_max=np.concatenate(SX), q_win=np.concatenate(QW),
                 q_task=np.array(QT), q_gold=np.array(QG), p_old=np.concatenate(PO),
                 ids=np.array([it["id"] for it in items]), units=np.array([it["unit"] for it in items]),
                 parts=np.array([it["part"] for it in items]), real=np.array([it["real"] for it in items]),
                 conf=np.array([it["conf"] for it in items]), text_sha=np.array([sha(it["text"]) for it in items]))
        print(f"{split}/{cond} done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)


# ------------------------------------------------------------------------------------------------ T, L2, L3, B1

NON_AUDIO = ("det", "text", "text0", "line")


def frames_for(split, groups, cond, src_dir, dst_dir, rows_by=None):
    ids = json.load(open(f"{src_dir}/sed_win_{split}_ids.json"))
    pos = {k: i for i, k in enumerate(ids)}
    frames = np.load(f"{src_dir}/sed_win_{split}_frames.npy")
    F = frames.copy()
    if cond != "natural":
        ev_cols = [D.DET_CLASSES.index(c) for c in EVENT]
        mv_cols = [D.DET_CLASSES.index(c) for c in MOVE]
        c = cval(cond)

        def put(i, g, cls, s0, s1):
            w0, n = g["t"] - D.WIN_S, F.shape[1]
            a, b = int(np.floor((s0 - w0) * FPS)), int(np.floor((s1 - w0) * FPS))
            a, b = max(a, 0), min(b, n - 1)
            if a <= b:
                F[i][a:b + 1, D.DET_CLASSES.index(cls)] = c
        for g in groups:
            base = pos[f"{g['unit']}|2|{g['k']}"]
            for v in g["versions"]:
                i = pos[f"{g['unit']}|{v}|{g['k']}"]
                F[i] = frames[base]
                F[i][:, ev_cols] = np.minimum(F[i][:, ev_cols], FRAME_CAP)
                if is_move(cond):                      # v0.6 15.1 (R-hear groups stay as "none")
                    if g["part"] == "s_move":
                        F[i][:, mv_cols] = np.minimum(F[i][:, mv_cols], FRAME_CAP)
                        for cls, s0, s1 in move_spans(rows_by[(g["unit"], "1")], g["t"]):
                            put(i, g, cls, s0, s1)
                elif c is not None:
                    cls, s0, s1 = g["event"]
                    put(i, g, cls, s0, s1)
    np.save(f"{dst_dir}/sed_win_{split}_frames.npy", F)


def copy_non_audio(split, groups, d):
    ids = json.load(open(f"{d}/l2_{split}_ids.json"))
    pos = {k: i for i, k in enumerate(ids)}
    for blk in NON_AUDIO:
        X = np.load(f"{d}/l2_{split}_{blk}.npy")
        for g in groups:
            base = pos[f"{g['unit']}|2|{g['k']}"]
            for v in g["versions"]:
                X[pos[f"{g['unit']}|{v}|{g['k']}"]] = X[base]
        np.save(f"{d}/l2_{split}_{blk}.npy", X)


def voxturn_matched(split):
    """Package 4.3 (since v0.3; code fixed 2026-11-21, review C-minor 4): in the matched conditions VoxTurn's questions
    get version 2's Whisper-small transcript of the line that ended at the point, identical for every version of a
    group, with each version's own audio; run as scripts/p1v4_voxturn.py (official VoxTurn, batch 16), group windows
    only. The transcript does not depend on the label condition, so one run serves every matched condition.
    Output grounding/<split>/voxturn_matched.json: {point id: [p, ...]} and "_text_sha" {point id: sha of the text}."""
    path = f"{out_dir(split)}/voxturn_matched.json"
    if os.path.exists(path):
        return json.load(open(path))
    import l1_voxturn
    import p1v4_l1 as L1
    import p1v4_voxturn as VT
    D.gpu_guard()
    rows, rows_by = load(split)
    groups = load_groups(split)
    ctx = C.Context(split, final=split != "dev")
    words = {}
    for g in groups:
        r2 = rows_by[(g["unit"], "2")]
        line = r2["points"][g["k"]].get("line")
        w2 = ctx.point(r2, g["k"])[0].get(line, "") if line else ""
        for v in g["versions"]:
            words[(g["unit"], v, g["k"])] = w2
    _, vt = l1_voxturn.load_official()
    ex, _ = L1.examples(split)
    ex = [e for e in ex if tuple(e["id"]) in words]
    names = [f"{q}:{lab}" for q in VT.QUESTIONS for lab in vt.questions[q]["labels"]]
    out = {"_columns": names, "_text_sha": {}}
    t0 = time.time()
    for b, (w, idx) in enumerate(L1.loader(ex, False, 16)):
        idx = idx.tolist()
        n = len(idx)
        lg = vt.logits(w.cuda(non_blocking=True), [True] * n, [words[tuple(ex[i]["id"])] for i in idx],
                       [ex[i]["marker"] for i in idx], ["en"] * n, [[(q, 0) for q in VT.QUESTIONS]] * n)
        p = lg.float().softmax(-1).cpu().numpy()
        for j, i in enumerate(idx):
            vals = []
            for k, q in enumerate(VT.QUESTIONS):
                vals += [round(float(x), 6) for x in p[j * len(VT.QUESTIONS) + k, :len(vt.questions[q]["labels"])]]
            pid = "|".join(map(str, ex[i]["id"]))
            out[pid] = vals
            out["_text_sha"][pid] = sha(words[tuple(ex[i]["id"])])
    os.makedirs(out_dir(split), exist_ok=True)
    json.dump(out, open(path, "w"))
    print(f"VoxTurn matched {split}: {len(ex)} group windows, {time.time() - t0:.0f} s", flush=True)
    return out


def voxturn_patch(split, d, vm):
    """Overwrite the group windows of the condition copy's VoxTurn answers with the matched run."""
    p = f"{d}/voxturn_{split}.json"
    vt = json.load(open(p))
    assert vt["_columns"] == vm["_columns"], "VoxTurn columns differ"
    n = 0
    for k, v in vm.items():
        if not k.startswith("_"):
            vt[k] = v
            n += 1
    json.dump(vt, open(p, "w"))
    return n


def non_audio_hashes(split, groups, d):
    ids = json.load(open(f"{d}/l2_{split}_ids.json"))
    pos = {k: i for i, k in enumerate(ids)}
    X = np.concatenate([np.load(f"{d}/l2_{split}_{blk}.npy") for blk in NON_AUDIO], 1)
    return {f"{g['unit']}|{v}|{g['k']}": sha(X[pos[f"{g['unit']}|{v}|{g['k']}"]]) for g in groups
            for v in g["versions"]}


def head_scores(L2, system, split, device="cuda"):
    """As scripts/p1v4_inject_pilot.py head_scores, for any split: the frozen T or L2 head on L2.FEATS's features."""
    import torch
    import torch.nn as nn
    ck = torch.load(f"{R}/{system}/{system}.pt", weights_only=False)            # our own file (numpy means)
    ids, X = L2.load_X(split, system)
    X = ((X - ck["mu"]) / ck["sd"]).astype(np.float32)
    dim = X.shape[1]
    net = nn.Linear(dim, 2) if ck["kind"] == "lr" else nn.Sequential(nn.Linear(dim, 256), nn.GELU(), nn.Dropout(0.2),
                                                                     nn.Linear(256, 2))
    net.load_state_dict(ck["state"])
    return L2.scores_of(net.to(device).eval(), X, ids, device)


def local_cmd(split):
    import torch
    import p1v4_b1 as B1
    import p1v4_l2 as L2
    import p1v4_l3 as L3
    D.gpu_guard()
    rows, rows_by = load(split)
    groups = load_groups(split)
    src = L2.FEATS
    chosen = json.load(open(f"{R}/b1/b1_dev.json"))["setting"]
    phrases = json.load(open(f"{R}/b1/mined_phrases.json"))
    vm = voxturn_matched(split)
    for cond in ALL_CONDS:
        d = f"{out_dir(split)}/feats_{cond}"
        done = f"{out_dir(split)}/local_{cond}.json"
        if os.path.exists(done):
            print(f"{cond}: exists, skipped", flush=True)
            continue
        os.makedirs(d, exist_ok=True)
        for f in (f"sed_win_{split}_ids.json", f"sed_win_{split}_emb.npy", f"voxturn_{split}.json"):
            shutil.copy(f"{src}/{f}", f"{d}/{f}")
        if cond != "natural":
            print(f"{cond}: VoxTurn answers of {voxturn_patch(split, d, vm)} group windows from the matched run",
                  flush=True)
        frames_for(split, groups, cond, src, d, rows_by)
        original = patch_context(groups, cond, rows_by) if cond != "natural" else None
        t0 = time.time()
        try:
            L2.FEATS = d                                   # features read and written in the copy only
            L2.features(split)
            if cond != "natural":
                copy_non_audio(split, groups, d)
            res = {"T": head_scores(L2, "t", split), "L2": head_scores(L2, "l2", split)}
            ck = torch.load(f"{R}/l3/l3.pt", weights_only=False)                # our own file (numpy means)
            wins, _, y, X, _, _ = L3.data(split, ck["mu"], ck["sd"])
            net = L3.Net(X.shape[1]).cuda()
            net.load_state_dict(ck["state"])
            res["L3"] = L3.score(net, wins, X, y)
            pts = B1.point_inputs(rows, C.Context(split), phrases)
            one = B1.Grid(np.array([[B1.GRID[n].index(chosen[n]) for n in B1.GRID]], np.int16))
            b1 = B1.decisions_for(pts, one, 0)
            hashes = non_audio_hashes(split, groups, d)
            if cond != "natural":                          # the identity check covers VoxTurn's text input too
                hashes = {k: sha(h + vm["_text_sha"][k]) for k, h in hashes.items()}
        finally:
            L2.FEATS = src
            if original is not None:
                C.Context = original
        keys = {f"{g['unit']}|{v}|{g['k']}" for g in groups for v in g["versions"]}
        out = {n: {"|".join(map(str, k)): v for k, v in sc.items() if "|".join(map(str, k)) in keys}
               for n, sc in res.items()}
        out["B1-strong"] = {"|".join(map(str, k)): v for k, v in b1.items() if "|".join(map(str, k)) in keys}
        out["non_audio_sha"] = hashes
        json.dump(out, open(done, "w"))
        print(f"{split}/{cond} local done in {time.time() - t0:.0f} s", flush=True)


# ------------------------------------------------------------------------------------------------ API

def api_mode_setting(system, split):
    """(answers?, setting) of an API system for this split (added 2026-11-20, freeze amendment third draft 2.2-2.6):
    the mode the test-day probe fixed (final/<split>/api/modes.json) and the frozen setting of that mode; on dev
    without a modes file, probabilities at the frozen dev choice."""
    import p1v4_api as A
    st = A.frozen(split)
    p = f"data/p1v4/runs/final/{split}/api/modes.json"
    mode = json.load(open(p))[A.NAME[system]] if os.path.exists(p) else ("probabilities" if split == "dev" else None)
    if mode is None:
        raise SystemExit(f"{p} missing: run the probe first (amendment 2.2)")
    return mode == "answers", A.effective(system, split, mode, st)["setting"]      # amendment 13.2: a re-choice wins


def api_effective(system, split):
    """(mode, the effective entry: setting, thresholds, override) of an API system, as the decision table uses them."""
    import p1v4_api as A
    answers, _ = api_mode_setting(system, split)
    mode = "answers" if answers else "probabilities"
    return mode, A.effective(system, split, mode, A.frozen(split))


def drift_ok_today(system, split):
    """Amendment 13.2 and its supplement for the package's API runs on test and replication: the same rule as
    p1v4_api.final_run (p1v4_api.ok_today: today's governing check passed at the effective setting, or a re-choice
    written today). Changed 2026-11-21 (post-fix review M5): one shared rule for every runner."""
    import p1v4_api as A
    ok, why = A.ok_today(system, split)
    if not ok:
        print(f"{A.NAME[system]}: {why}", flush=True)
    return ok


def api_dir(split, system, setting, answers, smoke=False):
    return os.path.join(out_dir(split), "api" + ("_smoke" if smoke else ""), system,
                        setting + ("_answers" if answers else ""))


def api_cmd(system, split, key_path, n_groups=None, conds=MATCHED, repeat=0, max_usd=1000.0, workers=16,
            setting=None, answers=None, rounds=6):
    """setting / answers override the frozen mode and setting (package v0.6 15.6: B3's second setting). Unanswered
    questions are re-asked in whole rounds (amendment 13.1); on test and replication any question still unanswered
    after the rounds stops the command before any metric."""
    import p1v4_api as A
    if split != "dev" and not drift_ok_today(system, split):
        raise SystemExit(f"{system}: no passed drift check (or re-choice) today on {split} (amendment 13.2)")
    a0, s0 = api_mode_setting(system, split)
    answers = a0 if answers is None else answers
    setting = s0 if setting is None else setting
    n, think, variant = A.parse_setting(system, setting)
    model = A.MODELS[system]
    rows, rows_by = load(split)
    groups = load_groups(split)
    if n_groups:
        rng = random.Random(0)
        by = {}
        for g in groups:
            by.setdefault(g["part"], []).append(g)
        share = {p: max(1, round(n_groups * len(v) / len(groups))) for p, v in by.items()}
        groups = [g for p in sorted(by) for g in rng.sample(by[p], min(share[p], len(by[p])))]
    pr = A.Prompts(system, n, split, variant)
    key = A.read_key(key_path)
    M = matched_context(C.Context)
    spent_all = 0.0
    for cond in conds:
        gs = [g for g in groups if g["part"] == "s_move"] if is_move(cond) else groups   # v0.6 15.1
        pr.ctx = M(split, groups, cond, rows_by, asr="turbo", final=split != "dev")
        d = os.path.join(api_dir(split, system, setting, answers, bool(n_groups)), cond)
        os.makedirs(d, exist_ok=True)
        path = os.path.join(d, "responses.jsonl")
        cases, texts = [], {}
        for g in gs:
            for v in (g["versions"] if system == "b3" else ["2"]):
                r = rows_by[(g["unit"], v)]
                case, qs = pr.case(r, g["k"])
                pid = f"{g['unit']}|{v}|{g['k']}"
                texts[pid] = sha(case)
                cases += [(pid, r, g["k"], case, q) for q in qs]
        json.dump(texts, open(os.path.join(d, "case_sha.json"), "w"))
        for rnd in range(rounds):
            done = set()
            if os.path.exists(path):
                for line in open(path, encoding="utf-8"):
                    rec = json.loads(line)
                    if rec["status"] == 200:
                        done.add((rec["id"], rec["q"]))
            items = [it for it in cases if (it[0], it[4]) not in done]
            if not items or spent_all >= max_usd:
                break
            if rnd:
                print(f"{cond}: round {rnd + 1}, {len(items)} unanswered questions asked again", flush=True)
            spent_all += run_items(A, key, model, pr, think, items, path, max_usd - spent_all, workers,
                                   f"{system} {setting} {cond}", logprobs=not answers)
        done = set()
        if os.path.exists(path):
            done = {(json.loads(x)["id"], json.loads(x)["q"]) for x in open(path, encoding="utf-8")
                    if json.loads(x)["status"] == 200}
        missing = sum(1 for it in cases if (it[0], it[4]) not in done)
        json.dump({"asked": len(cases), "missing": missing, "time": time.strftime("%Y-%m-%d %H:%M:%S")},
                  open(os.path.join(d, "missing.json"), "w"))
        if missing:
            msg = f"{system} {setting} {cond}: {missing} of {len(cases)} questions still unanswered"
            if split != "dev":
                raise SystemExit(msg + " (amendment 13.1: no metric with missing answers)")
            print("WARNING", msg, flush=True)
        if repeat and spent_all < max_usd:
            got = [json.loads(x) for x in open(path, encoding="utf-8")]
            ok = sorted({(rec["id"], rec["q"]) for rec in got if rec["status"] == 200})
            rpath = os.path.join(d, "repeat.jsonl")
            have = set()
            if os.path.exists(rpath):
                have = {(json.loads(x)["id"], json.loads(x)["q"]) for x in open(rpath, encoding="utf-8")
                        if json.loads(x)["status"] == 200}
            pick = random.Random(11).sample(ok, min(repeat, len(ok)))
            ritems = []
            for pid, q in pick:
                if (pid, q) in have:
                    continue
                u, v, k = pid.split("|")
                r = rows_by[(u, v)]
                case, _ = pr.case(r, int(k))
                ritems.append((pid, r, int(k), case, q))
            spent_all += run_items(A, key, model, pr, think, ritems, rpath, max_usd - spent_all, workers,
                                   f"{system} {setting} {cond} repeat", logprobs=not answers)
        if spent_all >= max_usd:
            print(f"budget reached (${spent_all:.2f}); stopped before the remaining conditions", flush=True)
            break
    print(f"{system} {split}: total ${spent_all:.2f}", flush=True)


def run_items(A, key, model, pr, think, items, path, max_usd, workers, label, logprobs=True):
    print(f"{label}: {len(items)} questions to ask; stop above ${max_usd:.0f}", flush=True)

    def work(it):
        pid, r, k, case, q = it
        st, js, dt, attempts = A.call(key, model, pr.parts(r, k, case, q), think, "standard", logprobs=logprobs)
        rec = {"id": pid, "q": q, "status": st, "latency_s": dt, "retries": attempts, "tier": "standard",
               "time": time.strftime("%Y-%m-%d %H:%M:%S")}
        if st == 200:
            rec.update(A.parse(js, q))
            rec["usage"] = {k2: v for k2, v in js.get("usageMetadata", {}).items() if isinstance(v, int)}
            rec["model_version"] = js.get("modelVersion")
            rec["usd"] = A.cost_of(model, rec["usage"], "standard")
        else:
            rec["error"] = js.get("error")
        return rec

    spent, n_ok, n_err, t0, stop, lost = 0.0, 0, 0, time.time(), None, False
    with open(path, "a", encoding="utf-8") as f, cf.ThreadPoolExecutor(workers) as ex:
        futs = [ex.submit(work, it) for it in items]
        try:
            for j, fu in enumerate(cf.as_completed(futs), 1):
                if fu.cancelled():
                    continue
                rec = fu.result()
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")
                f.flush()
                if rec["status"] == 200:
                    n_ok += 1
                    spent += rec["usd"]
                else:
                    n_err += 1
                    if n_err <= 5:
                        print(f"error {rec['status']}: {str(rec.get('error'))[:200]}", flush=True)
                if j % 200 == 0 or j == len(futs):
                    print(f"{label}: {j}/{len(futs)} ({n_err} errors), ${spent:.2f}, "
                          f"{(time.time() - t0) / 60:.1f} min", flush=True)
                no_lp = (logprobs and rec["status"] == 200 and rec.get("has_logprobs") is False
                         and rec.get("answer") is not None)   # review M4; fix check M1: not on a reply with no answer word
                if stop is None and (no_lp or spent > max_usd or (j >= 50 and n_err > 0.2 * j)):
                    lost = no_lp
                    stop = (f"{rec['id']} {rec['q']} came back without logprobs" if no_lp else
                            f"spent ${spent:.2f}" if spent > max_usd else f"{n_err} errors in {j} calls")
                    print("STOPPING:", stop, flush=True)
                    for x in futs:
                        x.cancel()
        except KeyboardInterrupt:
            for x in futs:
                x.cancel()
            raise
    print(f"{label}: {'stopped' if stop else 'finished'}, {n_ok} answered, {n_err} errors, ${spent:.2f}", flush=True)
    if lost:                                             # amendment 13.2: a probability-mode run stops at once
        raise SystemExit(f"{label}: logprobs lost in a probability-mode run; amendment 2.3: `p1v4_api.py switch "
                         f"<system> --split <split>`, then ask again (the answers folder starts from nothing)")
    return spent


# ------------------------------------------------------------------------------------------------ control

def control_cmd():
    """Natural-label control (plan 7.2): the train windows with their natural inputs, forwarded as in step 2, and
    the states read-out fitted on them exactly as scripts/p1v4_readout.py fit (same holdout, weight decays, epochs)."""
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    D.gpu_guard()
    d = f"{R}/grounding/control"
    os.makedirs(d, exist_ok=True)
    feats = f"{d}/feats_train_natural.npz"
    if not os.path.exists(feats):
        rows = D.load_rows("train")
        wins = D.windows_of(rows, "train")
        rows_by = {(r["unit"], r["version"]): r for r in rows}
        ctx = C.Context("train")
        model = L1.build()
        L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
        model.eval()
        items = []
        for w in wins:
            r = rows_by[w["key"]]
            text, asks = ctx.situation(r, w["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            items.append({"id": w["id"], "unit": w["unit"], "path": w["path"], "text": text,
                          "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                          "gold": [-1 if w["gold"].get(q) is None else
                                   int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs]})
        H, QW, QT, QG = [], [], [], []
        t0 = time.time()
        B = 8
        for i in range(0, len(items), B):
            chunk = items[i:i + B]
            waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
            h, _, qs, _ = RO.forward_states(model, waves, [it["text"] for it in chunk],
                                            [it["marker"] for it in chunk],
                                            [[RO.TASK[q] for q in it["qs"]] for it in chunk])
            H.append(h.astype(np.float16))
            QW.append(qs + i)
            QT += [q for it in chunk for q in it["qs"]]
            QG += [g for it in chunk for g in it["gold"]]
            if (i // B) % 500 == 0:
                print(f"train/natural: {i + len(chunk)}/{len(items)} windows {time.time() - t0:.0f} s", flush=True)
        np.savez(feats, states=np.concatenate(H), q_win=np.concatenate(QW), q_task=np.array(QT),
                 q_gold=np.array(QG), ids=np.array([it["id"] for it in items]),
                 units=np.array([it["unit"] for it in items]))
        print(f"train/natural done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)
    z = dict(np.load(feats))
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(RO.SEED)
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    X = z["states"].astype(np.float32)
    log, models = {}, {}
    for q in ("S", "R"):
        m = (z["q_task"] == q) & (z["q_gold"] >= 0)
        mu, sd = X[m].mean(0), X[m].std(0) + 1e-6
        Xs = ((X - mu) / sd).astype(np.float32)
        y = z["q_gold"]
        best = None
        for wd in RO.WDS:
            lin = RO.train_logreg(Xs[m & ~hold], y[m & ~hold], wd)
            p = np.clip(RO.predict(lin, Xs[m & hold]), 1e-7, 1 - 1e-7)
            yy = y[m & hold]
            ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
            log[f"states {q} wd {wd}"] = ll
            print(f"control states {q} wd {wd}: holdout log loss {ll:.4f}", flush=True)
            if best is None or ll < best[0]:
                best = (ll, wd)
        lin = RO.train_logreg(Xs[m], y[m], best[1])
        models[f"states|{q}"] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                                 "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
    np.savez(f"{d}/control_readouts.npz", **{f"{k}|{f}": v for k, dd in models.items() for f, v in dd.items()})
    json.dump(log, open(f"{d}/control_fit_log.json", "w"), indent=1)
    print("control read-out fitted:", {k: v["wd"] for k, v in models.items()}, flush=True)


def load_control():
    z = np.load(f"{R}/grounding/control/control_readouts.npz")
    out = {}
    for k in z.files:
        s, q, f = k.split("|")
        out.setdefault((s, q), {})[f] = z[k]
    return out


if __name__ == "__main__":
    a = sys.argv[1:]
    if a[0] == "groups":
        groups_cmd(a[1])
    elif a[0] == "l1":
        l1_cmd(a[1])
    elif a[0] == "local":
        local_cmd(a[1])
    elif a[0] == "voxturn":
        voxturn_matched(a[1])
    elif a[0] == "control":
        control_cmd()
    elif a[0] == "api":
        opts = dict(zip(a[4::2], a[5::2]))
        api_cmd(a[1], a[2], a[3], n_groups=int(opts["--groups"]) if "--groups" in opts else None,
                conds=tuple(opts["--conds"].split(",")) if "--conds" in opts else MATCHED + MOVE_CONDS,
                repeat=int(opts.get("--repeat", 0)), max_usd=float(opts.get("--max-usd", 1000)),
                workers=int(opts.get("--workers", 16)), setting=opts.get("--setting"),
                answers=None if "--answers" not in opts else opts["--answers"] == "1")
    else:
        raise SystemExit(__doc__)
